var paths=new [] {"Assets/Test/PlayerReactions/Animations/Test_GetUp.fbx","Assets/Test/PlayerReactions/Animations/Test_HeavyHit.fbx","Assets/Arts/Characters/Player/Animations/Fan/Test_SheathedIdle.fbx","Assets/Arts/Characters/Player/Models/Test_CheonPlayer.fbx"};
return paths.Select(path=> {var importer=(UnityEditor.ModelImporter)UnityEditor.AssetImporter.GetAtPath(path);var avatar=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path).OfType<Avatar>().FirstOrDefault();var so=new UnityEditor.SerializedObject(importer);return new {path,avatar=avatar==null?"missing":avatar.name,human=avatar!=null&&avatar.isHuman,valid=avatar!=null&&avatar.isValid,errors=so.FindProperty("m_AnimationImportErrors")?.stringValue,warnings=so.FindProperty("m_AnimationImportWarnings")?.stringValue,retarget=so.FindProperty("m_AnimationRetargetingWarnings")?.stringValue, skeleton=importer.humanDescription.skeleton.Where(b=>b.name.Contains("Hips")||b.name.Contains("Spine")||b.name.Contains("UpLeg")||b.name.Contains("LeftLeg")).Select(b=>new {b.name,position=b.position.ToString(),rotation=b.rotation.eulerAngles.ToString(),scale=b.scale.ToString()}).ToArray()};}).ToArray();

